    /** Is the theme on for this run? */
    public static boolean on() {
        String asked = System.getProperty("theme");
        if (asked != null) return onWord(asked);
        if (onCi()) return false;
        // SUITE_THEME can only turn it off: v1.14 left SUITE_THEME=cyberpunk in Windows' settings, and
        // a window still carrying that must never override "suite theme off".
        String chosen = System.getenv("SUITE_THEME");
        if (chosen != null && !onWord(chosen)) return false;
        String saved = saved("theme");
        return saved == null || !saved.equals("plain");
    }

    /** Music too? Only with the theme on, never on a build server. */
    static boolean sound() {
        if (!on() || onCi()) return false;
        String asked = System.getProperty("sound");
        if (asked != null) return onWord(asked);
        String chosen = System.getenv("SUITE_SOUND");
        if (chosen != null && !onWord(chosen)) return false;
        return !"false".equals(saved("sound"));
    }

    private static boolean onWord(String value) {
        String v = value.trim().toLowerCase(java.util.Locale.ROOT);
        return !(v.equals("off") || v.equals("plain") || v.equals("false") || v.equals("no") || v.equals("0"));
    }

    private static boolean onCi() {
        for (String name : CI_VARIABLES) if (System.getenv(name) != null) return true;
        return false;
    }

    /** A value from ~/.suite-builder/theme.json ("suite theme" writes it), or null. */
    private static String saved(String key) {
        try {
            java.nio.file.Path file = java.nio.file.Paths.get(System.getProperty("user.home"), ".suite-builder", "theme.json");
            if (!java.nio.file.Files.isRegularFile(file)) return null;
            String text = java.nio.file.Files.readString(file, java.nio.charset.StandardCharsets.UTF_8);
            int at = text.indexOf("\"" + key + "\"");
            if (at < 0) return null;
            int i = text.indexOf(':', at) + 1;
            while (i > 0 && i < text.length() && (text.charAt(i) == ' ' || text.charAt(i) == '"')) i++;
            int end = i;
            while (end < text.length() && Character.isLetterOrDigit(text.charAt(end))) end++;
            return i > 0 && end > i ? text.substring(i, end) : null;
        } catch (java.io.IOException | RuntimeException e) {
            return null;
        }
    }

